    <BaseAvatar.Root
      ref={ref}
      className={cx(styles.avatar, styles[size], agent && styles.agent, drawn && styles.illustrated, className)}
      role={decorative ? undefined : 'img'}
      aria-label={decorative ? undefined : label}
      aria-hidden={decorative || undefined}
