.links .segment {
  text-decoration-line: none;
}
.links .segment[aria-current="page"] {
  cursor: default;
}

export default { title: 'Forms/SegmentedControl' };
export const Default: Story = {};
export const Small: Story = {};
export const WithIcons: Story = {};
export const ThreeOptions: Story = {};
export const FullWidth: Story = {};
export const Disabled: Story = {};
export const Strong: Story = {};
export const ManyOnPhone: Story = {};
export const WithVisibleLabel: Story = {};
export const Links: Story = {};
export const AllStates: Story = {};

import { forwardRef, useCallback, useEffect, useRef, type HTMLAttributes, type ReactNode } from 'react';
import { RadioGroup as BaseRadioGroup } from '@base-ui/react/radio-group';
import { Radio as BaseRadio } from '@base-ui/react/radio';
import { cx } from '../../utils/cx';
import { Icon, type LucideIcon } from '../Icon';
import styles from './SegmentedControl.module.css';

export type SegmentedControlSize = 'sm' | 'md';
/** `default`: the selected segment is a raised plate. `strong`: it fills with Deep Harbor, only for the global space switch. */
export type SegmentedControlAppearance = 'default' | 'strong';

/** Extra attributes for one segment's button: `data-*` hooks a script reads, plus id and title. Behavior stays in the group. */
export interface SegmentAttributes {
  id?: string;
  title?: string;
  'aria-label'?: string;
  'aria-describedby'?: string;
  [key: `data-${string}`]: string | number | boolean | undefined;
}

export interface SegmentedControlItem {
  /** Value selected when this segment is chosen. */
  value: string;
  /** Visible label. Keep it to one or two words. */
  label: ReactNode;
  /** Lucide icon before the label. */
  icon?: LucideIcon;
  /** Decoration before the label that is not a Lucide icon, for example a color swatch. Hidden from assistive tech. */
  leading?: ReactNode;
  /** Count shown in a tag after the label, like the number of items behind a filter. */
  count?: number;
  disabled?: boolean;
  /**
   * Makes the control navigation: give every segment an `href` and each one is a link to its view, the current one
   * (`value`) marked `aria-current="page"`. The current segment may leave `href` out: it is the page you are on.
   */
  href?: string;
  /** Spread on the segment's button (or link). */
  attributes?: SegmentAttributes;
}

export interface SegmentedControlProps
  extends Omit<HTMLAttributes<HTMLDivElement>, 'children' | 'defaultValue' | 'onChange' | 'aria-label' | 'dir'> {
  /**
   * The segments, two or more. An array (not children) so the control also renders from Astro and other static
   * templates. When they do not fit (six filters on a phone), the track scrolls sideways inside its container and
   * never widens the page; the selected segment is scrolled into view.
   */
  items: SegmentedControlItem[];
  /** Accessible name of the group. Required unless you pass `aria-labelledby` pointing at a visible label. */
  label?: string;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Default `md`. Use `sm` in toolbars and dense panels. Heights follow the density tokens. */
  size?: SegmentedControlSize;
  /** Default `default` (the raised plate, link mode included). `strong` fills the selected segment with Deep Harbor: only the global space switch. */
  appearance?: SegmentedControlAppearance;
  /** Stretch to the container; segments share the width equally. */
  fullWidth?: boolean;
  disabled?: boolean;
  /** Form field name: the selected value is submitted with the form. */
  name?: string;
}

/** The scrolling part of a control: an inner track, so the fade never touches the outer border and background. */
const trackOf = (root: HTMLElement) => root.querySelector<HTMLElement>('[data-segment-track]') ?? root;

/** Marks which edges of a scrolling track hide segments (`data-overflow` on the root), so the CSS fades them. */
export function markSegmentOverflow(root: HTMLElement) {
  const track = trackOf(root);
  const max = track.scrollWidth - track.clientWidth;
  const start = track.scrollLeft > 1;
  const end = max - track.scrollLeft > 1;
  const value = start && end ? 'both' : start ? 'start' : end ? 'end' : null;
  if (value) root.setAttribute('data-overflow', value);
  else root.removeAttribute('data-overflow');
}

const SELECTED = '[data-segment][aria-checked="true"], [data-segment][aria-current="page"]';

/** Scrolls the track so the selected segment is fully visible, clear of the faded edge, without moving the page. */
function revealSelected(root: HTMLElement | null) {
  if (!root) return;
  const track = trackOf(root);
  if (track.scrollWidth <= track.clientWidth) return;
  const selected = track.querySelector<HTMLElement>(SELECTED);
  if (!selected) return;
  const pad = parseFloat(getComputedStyle(track).scrollPaddingInlineStart) || 0;
  const start = selected.offsetLeft - pad;
  const end = selected.offsetLeft + selected.offsetWidth + pad;
  if (start < track.scrollLeft) track.scrollLeft = Math.max(0, start);
  else if (end > track.scrollLeft + track.clientWidth) track.scrollLeft = end - track.clientWidth;
}

/**
 * One choice among a few views or modes, shown as a row of attached buttons. A Base UI RadioGroup whose
 * radios render native buttons: arrow keys move the selection, Tab leaves the group.
 *
 * Static contract (no hydration): the root carries `data-segmented-control`, each segment `data-segment` and
 * `data-value`, and the selected one `aria-checked="true"`. Styles read `aria-checked`, so a script that flips it
 * (and `tabindex`) drives a statically rendered control. A scrolling track fades the edges named by `data-overflow`
 * (`start`, `end`, `both`) on the root; the segments sit in an inner `data-segment-track` that scrolls: call
 * `markSegmentOverflow(root)` on its scroll and on resize.
 *
 * Links: when the items carry `href`, the control is navigation (a `nav` named by `label`), each segment a link and
 * the current one (`value`, or `defaultValue`) `aria-current="page"`. Tab moves between links; no radio semantics.
 */
export const SegmentedControl = forwardRef<HTMLDivElement, SegmentedControlProps>(function SegmentedControl(
  { items, label, value, defaultValue, onValueChange, size = 'md', appearance = 'default', fullWidth = false, disabled, name, className, ...rest },
  ref,
) {
  const local = useRef<HTMLDivElement | null>(null);
  const setRef = useCallback(
    (node: HTMLDivElement | null) => {
      local.current = node;
      if (typeof ref === 'function') ref(node);
      else if (ref) ref.current = node;
    },
    [ref],
  );
  // After a pick (or a controlled value change), keep the selected segment in view when the track scrolls.
  useEffect(() => {
    const raf = requestAnimationFrame(() => revealSelected(local.current));
    return () => cancelAnimationFrame(raf);
  }, [value]);
  // Fade the edges that hide segments, as the track scrolls or its container resizes.
  useEffect(() => {
    const root = local.current;
    if (!root) return;
    const track = trackOf(root);
    const mark = () => markSegmentOverflow(root);
    mark();
    track.addEventListener('scroll', mark, { passive: true });
    const observer = typeof ResizeObserver === 'undefined' ? null : new ResizeObserver(mark);
    observer?.observe(track);
    return () => {
      track.removeEventListener('scroll', mark);
      observer?.disconnect();
    };
  }, []);

  const content = (item: SegmentedControlItem) => (
    <>
      {item.leading != null && (
        <span className={styles.leading} aria-hidden="true">
          {item.leading}
        </span>
      )}
      {item.icon && <Icon icon={item.icon} size="sm" className={styles.icon} />}
      <span className={styles.label}>{item.label}</span>
      {item.count !== undefined && (
        <>
          {' '}
          <span className={styles.count}>{item.count}</span>
        </>
      )}
    </>
  );
  const rootClass = cx(styles.root, styles[size], appearance === 'strong' && styles.strong, fullWidth && styles.fullWidth, className);

  if (items.some((item) => item.href !== undefined)) {
    const current = value ?? defaultValue;
    return (
      <nav ref={setRef as never} aria-label={label} className={cx(rootClass, styles.links)} data-segmented-control="" {...rest}>
        <div className={styles.track} data-segment-track="">
          {items.map((item) => {
            const here = item.value === current;
            const off = disabled || item.disabled;
            return (
              <a
                key={item.value}
                href={off ? undefined : item.href}
                aria-current={here ? 'page' : undefined}
                aria-disabled={off || undefined}
                data-disabled={off || undefined}
                className={styles.segment}
                data-segment=""
                data-value={item.value}
                onClick={() => onValueChange?.(item.value)}
                {...item.attributes}
              >
                {content(item)}
              </a>
            );
          })}
        </div>
      </nav>
    );
  }

  return (
    <BaseRadioGroup
      ref={setRef}
      aria-label={label}
      aria-orientation="horizontal"
      value={value}
      defaultValue={defaultValue}
      onValueChange={(v: unknown) => {
        onValueChange?.(v as string);
        requestAnimationFrame(() => revealSelected(local.current));
      }}
      disabled={disabled}
      name={name}
      className={rootClass}
      data-segmented-control=""
      {...rest}
    >
      <div className={styles.track} data-segment-track="">
        {items.map((item) => (
          <BaseRadio.Root
            key={item.value}
            value={item.value}
            disabled={item.disabled}
            nativeButton
            render={<button type="button" />}
            className={styles.segment}
            data-segment=""
            data-value={item.value}
            {...item.attributes}
          >
            {content(item)}
          </BaseRadio.Root>
        ))}
      </div>
    </BaseRadioGroup>
  );
});

